  Exercise(id:"python-c2-t0-classwork-complete-v1", topic:"python-c2-t0", category:"Classwork", type:"code", title:"Countdown", prompt:"Read a valid nonnegative integer. Print every positive integer from that value down to 1, one per line, followed by Done. Use while.", tests:[{"input": ["3"], "harness": "", "expected": "3\n2\n1\nDone", "comparison": "normalized"}, {"input": ["0"], "harness": "", "expected": "Done", "comparison": "normalized"}, {"input": ["1"], "harness": "", "expected": "1\nDone", "comparison": "normalized"}], hints:["Compare the state before and after one repetition."], solution:"n=int(input())\nwhile n>0:\n    print(n)\n    n-=1\nprint(\"Done\")\n\nReasoning: Compare the state before and after one repetition. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t0-homework-complete-v1", topic:"python-c2-t0", category:"Homework", type:"code", title:"Repeated doubling", prompt:"Define double_until(start, limit). Both arguments are positive integers. Repeatedly double start until it is at least limit, then return it. Do not print.", tests:[{"input": [], "harness": "result=double_until(3,20)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "24", "comparison": "numeric"}, {"input": [], "harness": "result=double_until(8,8)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "8", "comparison": "numeric"}, {"input": [], "harness": "result=double_until(1,9)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "16", "comparison": "numeric"}], hints:["What quantity moves towards the stopping rule?"], solution:"def double_until(start,limit):\n    while start<limit:\n        start*=2\n    return start\n\nReasoning: What quantity moves towards the stopping rule? Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t0-challenge-complete-v1", topic:"python-c2-t0", category:"Challenge", type:"code", title:"Savings milestone", prompt:"Define months_needed(balance, deposit, goal). balance and goal are nonnegative integers; deposit is positive. Return the minimum whole months needed to reach goal by adding deposit each month.", tests:[{"input": [], "harness": "result=months_needed(10,7,30)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "3", "comparison": "numeric"}, {"input": [], "harness": "result=months_needed(30,7,30)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0", "comparison": "numeric"}, {"input": [], "harness": "result=months_needed(0,5,11)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "3", "comparison": "numeric"}], hints:["Track both the changing amount and the number of changes."], solution:"def months_needed(balance,deposit,goal):\n    months=0\n    while balance<goal:\n        balance+=deposit\n        months+=1\n    return months\n\nReasoning: Track both the changing amount and the number of changes. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t0-project-complete-v1", topic:"python-c2-t0", category:"Project", type:"code", title:"Report countdown stage", prompt:"Read a positive number of reporting rounds. Print Round N down to Round 1, then Report ready. This is the first repetition stage of your mock report project.", tests:[{"input": ["2"], "harness": "", "expected": "Round 2\nRound 1\nReport ready", "comparison": "normalized"}, {"input": ["1"], "harness": "", "expected": "Round 1\nReport ready", "comparison": "normalized"}], hints:["Choose a state that has an obvious end."], solution:"n=int(input())\nwhile n>0:\n    print(f\"Round {n}\")\n    n-=1\nprint(\"Report ready\")\n\nReasoning: Choose a state that has an obvious end. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t0-assessment-complete-0-v1", topic:"python-c2-t0", category:"Assessment", type:"short", title:"Understanding check 1", prompt:"Can a while body run zero times? Answer yes or no.", accepted:["yes"], solution:"Answer: yes", required:false),
  Exercise(id:"python-c2-t0-assessment-complete-1-v1", topic:"python-c2-t0", category:"Assessment", type:"short", title:"Understanding check 2", prompt:"What is the final value of n after the lesson example?", accepted:["0"], solution:"Answer: 0", required:false),
