  Exercise(id:"python-c2-t0-assessment-complete-3-v1", topic:"python-c2-t0", category:"Assessment", type:"short", title:"Understanding check 4", prompt:"Is the condition checked before each iteration? Answer yes or no.", accepted:["yes"], solution:"Answer: yes", required:false),
  Exercise(id:"python-c2-t1-classwork-complete-v1", topic:"python-c2-t1", category:"Classwork", type:"code", title:"Inclusive sequence", prompt:"Read a valid nonnegative integer n. Print 1 through n, one number per line. For zero, print nothing. Use for and range.", tests:[{"input": ["3"], "harness": "", "expected": "1\n2\n3", "comparison": "normalized"}, {"input": ["0"], "harness": "", "expected": "", "comparison": "normalized"}, {"input": ["1"], "harness": "", "expected": "1", "comparison": "normalized"}], hints:["Write the intended sequence before its bounds."], solution:"n=int(input())\nfor i in range(1,n+1):\n    print(i)\n\nReasoning: Write the intended sequence before its bounds. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t1-homework-complete-v1", topic:"python-c2-t1", category:"Homework", type:"code", title:"Sum of squares", prompt:"Define sum_squares(n), for nonnegative integer n. Return 1² + 2² + ... + n²; zero returns zero.", tests:[{"input": [], "harness": "result=sum_squares(3)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "14", "comparison": "numeric"}, {"input": [], "harness": "result=sum_squares(0)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0", "comparison": "numeric"}, {"input": [], "harness": "result=sum_squares(5)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "55", "comparison": "numeric"}], hints:["Separate the changing term from the running total."], solution:"def sum_squares(n):\n    total=0\n    for i in range(1,n+1):\n        total+=i*i\n    return total\n\nReasoning: Separate the changing term from the running total. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t1-challenge-complete-v1", topic:"python-c2-t1", category:"Challenge", type:"code", title:"Every third marker", prompt:"Define marker_total(n). Return the sum of nonnegative multiples of three strictly below nonnegative integer n.", tests:[{"input": [], "harness": "result=marker_total(10)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "18", "comparison": "numeric"}, {"input": [], "harness": "result=marker_total(3)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0", "comparison": "numeric"}, {"input": [], "harness": "result=marker_total(7)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "9", "comparison": "numeric"}], hints:["The final boundary is explicitly excluded."], solution:"def marker_total(n):\n    total=0\n    for i in range(0,n,3):\n        total+=i\n    return total\n\nReasoning: The final boundary is explicitly excluded. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t1-project-complete-v1", topic:"python-c2-t1", category:"Project", type:"code", title:"Session report stage", prompt:"Read a nonnegative session count. For each session, read a valid nonnegative integer minute value and print Session INDEX: MINUTES. INDEX starts at 1. Then print Sessions recorded: COUNT.", tests:[{"input": ["2", "20", "35"], "harness": "", "expected": "Session 1: 20\nSession 2: 35\nSessions recorded: 2", "comparison": "normalized"}, {"input": ["0"], "harness": "", "expected": "Sessions recorded: 0", "comparison": "normalized"}], hints:["Distinguish the repetition count from the values collected."], solution:"count=int(input())\nfor i in range(1,count+1):\n    minutes=int(input())\n    print(f\"Session {i}: {minutes}\")\nprint(f\"Sessions recorded: {count}\")\n\nReasoning: Distinguish the repetition count from the values collected. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
