  Exercise(id:"python-c2-t2-classwork-complete-v1", topic:"python-c2-t2", category:"Classwork", type:"code", title:"Ordered display", prompt:"Define display_values(values). Print each element of the supplied list on its own line. An empty list prints nothing.", tests:[{"input": [], "harness": "display_values([2,5])", "expected": "2\n5", "comparison": "normalized"}, {"input": [], "harness": "display_values([])", "expected": "", "comparison": "normalized"}, {"input": [], "harness": "display_values([0])", "expected": "0", "comparison": "normalized"}], hints:["Preserve the original order."], solution:"def display_values(values):\n    for value in values:\n        print(value)\n\nReasoning: Preserve the original order. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t2-homework-complete-v1", topic:"python-c2-t2", category:"Homework", type:"code", title:"Filter long sessions", prompt:"Define long_sessions(values). Return a new list containing values at least 30, preserving order. Input is a list of nonnegative integers. Do not mutate it.", tests:[{"input": [], "harness": "print(long_sessions([29,30,45,0]))", "expected": "[30, 45]", "comparison": "normalized"}, {"input": [], "harness": "print(long_sessions([]))", "expected": "[]", "comparison": "normalized"}, {"input": [], "harness": "print(long_sessions([60,30]))", "expected": "[60, 30]", "comparison": "normalized"}], hints:["Ask whether each observation belongs in the result."], solution:"def long_sessions(values):\n    result=[]\n    for value in values:\n        if value>=30:\n            result.append(value)\n    return result\n\nReasoning: Ask whether each observation belongs in the result. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t2-challenge-complete-v1", topic:"python-c2-t2", category:"Challenge", type:"code", title:"Adjacent rises", prompt:"Define rise_count(values). Return how many adjacent pairs rise: the later value is strictly larger. Empty and one-element lists return zero.", tests:[{"input": [], "harness": "result=rise_count([2,5,5,1,3])\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "2", "comparison": "numeric"}, {"input": [], "harness": "result=rise_count([])\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0", "comparison": "numeric"}, {"input": [], "harness": "result=rise_count([9])\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0", "comparison": "numeric"}], hints:["A comparison needs two neighbouring observations."], solution:"def rise_count(values):\n    count=0\n    for i in range(1,len(values)):\n        if values[i]>values[i-1]:\n            count+=1\n    return count\n\nReasoning: A comparison needs two neighbouring observations. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t2-project-complete-v1", topic:"python-c2-t2", category:"Project", type:"code", title:"Reusable session analysis", prompt:"Define session_summary(values). Return [total minutes, count of sessions at least 30]. Input is a list of nonnegative integers; an empty list returns [0,0]. This extends your session report to reusable stored records.", tests:[{"input": [], "harness": "print(session_summary([20,30,40]))", "expected": "[90, 2]", "comparison": "normalized"}, {"input": [], "harness": "print(session_summary([]))", "expected": "[0, 0]", "comparison": "normalized"}, {"input": [], "harness": "print(session_summary([0,29]))", "expected": "[29, 0]", "comparison": "normalized"}], hints:["One pass can maintain different summaries."], solution:"def session_summary(values):\n    total=0\n    long_count=0\n    for value in values:\n        total+=value\n        if value>=30:\n            long_count+=1\n    return [total,long_count]\n\nReasoning: One pass can maintain different summaries. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
