  Exercise(id:"python-c2-t3-classwork-complete-v1", topic:"python-c2-t3", category:"Classwork", type:"code", title:"Lookup with a default", prompt:"Define recorded_minutes(records, subject). Return the value for subject, or zero when absent. records maps text keys to nonnegative integer values.", tests:[{"input": [], "harness": "result=recorded_minutes({'Python':30},'Python')\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "30", "comparison": "numeric"}, {"input": [], "harness": "result=recorded_minutes({},'Maths')\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0", "comparison": "numeric"}, {"input": [], "harness": "result=recorded_minutes({'Python':0},'Python')\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0", "comparison": "numeric"}], hints:["Absence and a stored zero can have the same numeric result."], solution:"def recorded_minutes(records,subject):\n    return records.get(subject,0)\n\nReasoning: Absence and a stored zero can have the same numeric result. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t3-homework-complete-v1", topic:"python-c2-t3", category:"Homework", type:"code", title:"Count named observations", prompt:"Define frequencies(names). Return a dictionary counting each exact text value in a list. Keys are case-sensitive.", tests:[{"input": [], "harness": "print(frequencies(['A','B','A']))", "expected": "{'A': 2, 'B': 1}", "comparison": "normalized"}, {"input": [], "harness": "print(frequencies([]))", "expected": "{}", "comparison": "normalized"}, {"input": [], "harness": "print(frequencies(['a','A']))", "expected": "{'a': 1, 'A': 1}", "comparison": "normalized"}], hints:["Repeated keys must update rather than discard the previous count."], solution:"def frequencies(names):\n    result={}\n    for name in names:\n        result[name]=result.get(name,0)+1\n    return result\n\nReasoning: Repeated keys must update rather than discard the previous count. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t3-challenge-complete-v1", topic:"python-c2-t3", category:"Challenge", type:"code", title:"Highest total, tied names", prompt:"Define leaders(records). Return a sorted list of all keys tied for the largest numeric value; empty input returns [].", tests:[{"input": [], "harness": "print(leaders({'B':5,'A':5,'C':2}))", "expected": "['A', 'B']", "comparison": "normalized"}, {"input": [], "harness": "print(leaders({}))", "expected": "[]", "comparison": "normalized"}, {"input": [], "harness": "print(leaders({'Z':0}))", "expected": "['Z']", "comparison": "normalized"}], hints:["A tie means the result may contain more than one name."], solution:"def leaders(records):\n    if not records:\n        return []\n    highest=max(records.values())\n    result=[]\n    for key,value in records.items():\n        if value==highest:\n            result.append(key)\n    return sorted(result)\n\nReasoning: A tie means the result may contain more than one name. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t3-project-complete-v1", topic:"python-c2-t3", category:"Project", type:"code", title:"Subject totals stage", prompt:"Define subject_totals(records). Each record is [subject, minutes], with a text subject and nonnegative integer minutes. Return totals by exact subject. Preserve first-seen key order.", tests:[{"input": [], "harness": "print(subject_totals([['Python',20],['Maths',10],['Python',30]]))", "expected": "{'Python': 50, 'Maths': 10}", "comparison": "normalized"}, {"input": [], "harness": "print(subject_totals([]))", "expected": "{}", "comparison": "normalized"}, {"input": [], "harness": "print(subject_totals([['ICT',0]]))", "expected": "{'ICT': 0}", "comparison": "normalized"}], hints:["Use the same record format as your session list."], solution:"def subject_totals(records):\n    totals={}\n    for subject,minutes in records:\n        totals[subject]=totals.get(subject,0)+minutes\n    return totals\n\nReasoning: Use the same record format as your session list. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t3-assessment-complete-0-v1", topic:"python-c2-t3", category:"Assessment", type:"short", title:"Understanding check 1", prompt:"Which exception does missing dictionary[key] raise?", accepted:["keyerror"], solution:"Answer: keyerror", required:false),
  Exercise(id:"python-c2-t3-assessment-complete-1-v1", topic:"python-c2-t3", category:"Assessment", type:"short", title:"Understanding check 2", prompt:"Does key in mapping test keys or values?", accepted:["keys"], solution:"Answer: keys", required:false),
  Exercise(id:"python-c2-t3-assessment-complete-2-v1", topic:"python-c2-t3", category:"Assessment", type:"short", title:"Understanding check 3", prompt:"Can a dictionary retain two separate entries with an identical key? Answer yes or no.", accepted:["no"], solution:"Answer: no", required:false),
  Exercise(id:"python-c2-t3-assessment-complete-3-v1", topic:"python-c2-t3", category:"Assessment", type:"short", title:"Understanding check 4", prompt:"Does iterating directly over a dictionary yield keys? Answer yes or no.", accepted:["yes"], solution:"Answer: yes", required:false),
  Exercise(id:"python-c2-t4-classwork-complete-v1", topic:"python-c2-t4", category:"Classwork", type:"code", title:"Qualifying count", prompt:"Define count_at_least(values, threshold). Return how many numeric observations are at least threshold.", tests:[{"input": [], "harness": "result=count_at_least([10,30,40],30)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "2", "comparison": "numeric"}, {"input": [], "harness": "result=count_at_least([],0)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0", "comparison": "numeric"}, {"input": [], "harness": "result=count_at_least([-2,0,2],0)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "2", "comparison": "numeric"}], hints:["Keep a record of qualifying events, not their sum."], solution:"def count_at_least(values,threshold):\n    count=0\n    for value in values:\n        if value>=threshold:\n            count+=1\n    return count\n\nReasoning: Keep a record of qualifying events, not their sum. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t4-homework-complete-v1", topic:"python-c2-t4", category:"Homework", type:"code", title:"Average with an empty policy", prompt:"Define mean_minutes(values). Return their arithmetic mean; an empty list returns 0. Values are nonnegative numbers.", tests:[{"input": [], "harness": "result=mean_minutes([10,20,30])\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "20", "comparison": "numeric"}, {"input": [], "harness": "result=mean_minutes([])\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0", "comparison": "numeric"}, {"input": [], "harness": "result=mean_minutes([0,5])\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "2.5", "comparison": "numeric"}], hints:["Choose the denominator from the actual observations."], solution:"def mean_minutes(values):\n    if not values:\n        return 0\n    total=0\n    for value in values:\n        total+=value\n    return total/len(values)\n\nReasoning: Choose the denominator from the actual observations. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t4-challenge-complete-v1", topic:"python-c2-t4", category:"Challenge", type:"code", title:"Stop at the sentinel", prompt:"Define sum_before_stop(values). Add numbers until the first -1; do not include -1 or anything after it. If absent, add all values.", tests:[{"input": [], "harness": "result=sum_before_stop([3,4,-1,100])\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "7", "comparison": "numeric"}, {"input": [], "harness": "result=sum_before_stop([-1,5])\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0", "comparison": "numeric"}, {"input": [], "harness": "result=sum_before_stop([2,3])\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "5", "comparison": "numeric"}], hints:["The stopping marker is control information, not an observation."], solution:"def sum_before_stop(values):\n    total=0\n    for value in values:\n        if value==-1:\n            break\n        total+=value\n    return total\n\nReasoning: The stopping marker is control information, not an observation. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t4-project-complete-v1", topic:"python-c2-t4", category:"Project", type:"code", title:"Loops chapter: study dashboard", prompt:"Define build_report(records, target). records is a list of [subject, nonnegative integer minutes]; target is a positive integer. Return [total_minutes, session_count, sessions_at_least_30, percentage_of_target]. Do not print or mutate records. In My Notes explain how subject_totals from the previous stage can extend this report.", tests:[{"input": [], "harness": "print(build_report([['Python',30],['Maths',20],['Python',40]],100))", "expected": "[90, 3, 2, 90.0]", "comparison": "normalized"}, {"input": [], "harness": "print(build_report([],60))", "expected": "[0, 0, 0, 0.0]", "comparison": "normalized"}, {"input": [], "harness": "print(build_report([['ICT',60]],30))", "expected": "[60, 1, 1, 200.0]", "comparison": "normalized"}], hints:["Combine the earlier stages without changing their meaning."], solution:"def build_report(records,target):\n    total=0\n    count=0\n    for subject,minutes in records:\n        total+=minutes\n        if minutes>=30:\n            count+=1\n    return [total,len(records),count,total/target*100]\n\nReasoning: Combine the earlier stages without changing their meaning. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c2-t4-assessment-complete-0-v1", topic:"python-c2-t4", category:"Assessment", type:"short", title:"Understanding check 1", prompt:"Should an accumulator be reset inside every iteration? Answer yes or no.", accepted:["no"], solution:"Answer: no", required:false),
  Exercise(id:"python-c2-t4-assessment-complete-1-v1", topic:"python-c2-t4", category:"Assessment", type:"short", title:"Understanding check 2", prompt:"Which keyword exits the nearest loop?", accepted:["break"], solution:"Answer: break", required:false),
  Exercise(id:"python-c2-t4-assessment-complete-2-v1", topic:"python-c2-t4", category:"Assessment", type:"short", title:"Understanding check 3", prompt:"Which keyword skips the remainder of one iteration?", accepted:["continue"], solution:"Answer: continue", required:false),
  Exercise(id:"python-c2-t4-assessment-complete-3-v1", topic:"python-c2-t4", category:"Assessment", type:"short", title:"Understanding check 4", prompt:"Two outer iterations each run three inner iterations. How many inner executions occur?", accepted:["6"], solution:"Answer: 6", required:false),
  Exercise(id:"python-c3-t0-classwork-complete-v1", topic:"python-c3-t0", category:"Classwork", type:"code", title:"Handle numeric text", prompt:"Read one string. Convert it with int. Print Value: NUMBER on success or Invalid integer on ValueError.", tests:[{"input": ["12"], "harness": "", "expected": "Value: 12", "comparison": "normalized"}, {"input": ["bad"], "harness": "", "expected": "Invalid integer", "comparison": "normalized"}, {"input": ["3.5"], "harness": "", "expected": "Invalid integer", "comparison": "normalized"}], hints:["Identify the exact operation whose assumption may fail."], solution:"text=input()\ntry:\n    number=int(text)\nexcept ValueError:\n    print(\"Invalid integer\")\nelse:\n    print(f\"Value: {number}\")\n\nReasoning: Identify the exact operation whose assumption may fail. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c3-t0-homework-complete-v1", topic:"python-c3-t0", category:"Homework", type:"code", title:"Safe division policy", prompt:"Define divide_or_none(a,b). Numeric arguments are supplied. Return a/b, or None on ZeroDivisionError. Do not catch unrelated types.", tests:[{"input": [], "harness": "result=divide_or_none(8,2)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "4.0", "comparison": "numeric"}, {"input": [], "harness": "print(divide_or_none(1,0))", "expected": "None", "comparison": "normalized"}, {"input": [], "harness": "result=divide_or_none(-6,3)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "-2.0", "comparison": "numeric"}], hints:["A zero denominator is a different failure from invalid text."], solution:"def divide_or_none(a,b):\n    try:\n        return a/b\n    except ZeroDivisionError:\n        return None\n\nReasoning: A zero denominator is a different failure from invalid text. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c3-t0-challenge-complete-v1", topic:"python-c3-t0", category:"Challenge", type:"code", title:"Missing versus stored zero", prompt:"Define lookup_or_none(records,key). Return records[key], or None only on KeyError. A stored zero must remain zero.", tests:[{"input": [], "harness": "result=lookup_or_none({'A':0},'A')\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0", "comparison": "numeric"}, {"input": [], "harness": "print(lookup_or_none({},'A'))", "expected": "None", "comparison": "normalized"}, {"input": [], "harness": "result=lookup_or_none({'B':9},'B')\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "9", "comparison": "numeric"}], hints:["Do not confuse absence with a valid falsy value."], solution:"def lookup_or_none(records,key):\n    try:\n        return records[key]\n    except KeyError:\n        return None\n\nReasoning: Do not confuse absence with a valid falsy value. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c3-t0-project-complete-v1", topic:"python-c3-t0", category:"Project", type:"code", title:"Diagnostic report stage", prompt:"Read an integer minute count as text. Print Invalid integer if conversion fails; otherwise print Minutes: NUMBER, even if negative. Domain validation is the next stage, not part of this question.", tests:[{"input": ["30"], "harness": "", "expected": "Minutes: 30", "comparison": "normalized"}, {"input": ["oops"], "harness": "", "expected": "Invalid integer", "comparison": "normalized"}, {"input": ["-1"], "harness": "", "expected": "Minutes: -1", "comparison": "normalized"}], hints:["Conversion and permitted values are separate decisions."], solution:"text=input()\ntry:\n    minutes=int(text)\nexcept ValueError:\n    print(\"Invalid integer\")\nelse:\n    print(f\"Minutes: {minutes}\")\n\nReasoning: Conversion and permitted values are separate decisions. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c3-t0-assessment-complete-0-v1", topic:"python-c3-t0", category:"Assessment", type:"short", title:"Understanding check 1", prompt:"Which exception does int(\"bad\") raise?", accepted:["valueerror"], solution:"Answer: valueerror", required:false),
  Exercise(id:"python-c3-t0-assessment-complete-1-v1", topic:"python-c3-t0", category:"Assessment", type:"short", title:"Understanding check 2", prompt:"Which exception does 1/0 raise?", accepted:["zerodivisionerror"], solution:"Answer: zerodivisionerror", required:false),
  Exercise(id:"python-c3-t0-assessment-complete-2-v1", topic:"python-c3-t0", category:"Assessment", type:"short", title:"Understanding check 3", prompt:"Does except ValueError automatically catch TypeError? Answer yes or no.", accepted:["no"], solution:"Answer: no", required:false),
  Exercise(id:"python-c3-t0-assessment-complete-3-v1", topic:"python-c3-t0", category:"Assessment", type:"short", title:"Understanding check 4", prompt:"After a handled exception, can execution continue? Answer yes or no.", accepted:["yes"], solution:"Answer: yes", required:false),
  Exercise(id:"python-c3-t1-classwork-complete-v1", topic:"python-c3-t1", category:"Classwork", type:"code", title:"Convert then validate", prompt:"Read one string. Print Invalid integer if int conversion fails, Negative if converted value is below zero, otherwise Accepted: NUMBER.", tests:[{"input": ["bad"], "harness": "", "expected": "Invalid integer", "comparison": "normalized"}, {"input": ["-2"], "harness": "", "expected": "Negative", "comparison": "normalized"}, {"input": ["0"], "harness": "", "expected": "Accepted: 0", "comparison": "normalized"}], hints:["Two different checks need two different outcomes."], solution:"try:\n    value=int(input())\nexcept ValueError:\n    print(\"Invalid integer\")\nelse:\n    if value<0:\n        print(\"Negative\")\n    else:\n        print(f\"Accepted: {value}\")\n\nReasoning: Two different checks need two different outcomes. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c3-t1-homework-complete-v1", topic:"python-c3-t1", category:"Homework", type:"code", title:"First permitted observation", prompt:"Define first_valid(texts). Return the first text converting to a nonnegative integer; skip invalid or negative values. Return None if none qualify. Do not mutate texts.", tests:[{"input": [], "harness": "result=first_valid(['bad','-2','0','9'])\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0", "comparison": "numeric"}, {"input": [], "harness": "print(first_valid(['bad','-1']))", "expected": "None", "comparison": "normalized"}, {"input": [], "harness": "print(first_valid([]))", "expected": "None", "comparison": "normalized"}], hints:["The first accepted value may be zero."], solution:"def first_valid(texts):\n    for text in texts:\n        try:\n            value=int(text)\n        except ValueError:\n            continue\n        if value>=0:\n            return value\n    return None\n\nReasoning: The first accepted value may be zero. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c3-t1-challenge-complete-v1", topic:"python-c3-t1", category:"Challenge", type:"code", title:"Bounded attempts", prompt:"Read exactly up to three responses seeking a nonnegative integer. For each invalid or negative response print Retry. On success print Accepted: NUMBER and stop. After three failures print Unavailable. Inputs supply enough lines for the attempted reads.", tests:[{"input": ["bad", "-1", "4"], "harness": "", "expected": "Retry\nRetry\nAccepted: 4", "comparison": "normalized"}, {"input": ["0"], "harness": "", "expected": "Accepted: 0", "comparison": "normalized"}, {"input": ["bad", "bad", "bad"], "harness": "", "expected": "Retry\nRetry\nRetry\nUnavailable", "comparison": "normalized"}], hints:["Account for both success and exhausted attempts."], solution:"for attempt in range(3):\n    try:\n        value=int(input())\n    except ValueError:\n        print(\"Retry\")\n        continue\n    if value<0:\n        print(\"Retry\")\n        continue\n    print(f\"Accepted: {value}\")\n    break\nelse:\n    print(\"Unavailable\")\n\nReasoning: Account for both success and exhausted attempts. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c3-t1-project-complete-v1", topic:"python-c3-t1", category:"Project", type:"code", title:"Accepted and rejected sessions", prompt:"Define validated_sessions(texts). Return [accepted_list, rejected_count]. Accept text convertible to a nonnegative integer, preserving order; invalid and negative entries each increase rejected_count.", tests:[{"input": [], "harness": "print(validated_sessions(['20','bad','-1','0']))", "expected": "[[20, 0], 2]", "comparison": "normalized"}, {"input": [], "harness": "print(validated_sessions([]))", "expected": "[[], 0]", "comparison": "normalized"}, {"input": [], "harness": "print(validated_sessions(['30','40']))", "expected": "[[30, 40], 0]", "comparison": "normalized"}], hints:["A rejected record must not erase accepted ones."], solution:"def validated_sessions(texts):\n    accepted=[]\n    rejected=0\n    for text in texts:\n        try:\n            value=int(text)\n        except ValueError:\n            rejected+=1\n            continue\n        if value<0:\n            rejected+=1\n        else:\n            accepted.append(value)\n    return [accepted,rejected]\n\nReasoning: A rejected record must not erase accepted ones. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c3-t1-assessment-complete-0-v1", topic:"python-c3-t1", category:"Assessment", type:"short", title:"Understanding check 1", prompt:"Does int(\"-5\") fail conversion? Answer yes or no.", accepted:["no"], solution:"Answer: no", required:false),
  Exercise(id:"python-c3-t1-assessment-complete-1-v1", topic:"python-c3-t1", category:"Assessment", type:"short", title:"Understanding check 2", prompt:"Does the try else body run when conversion raised ValueError? Answer yes or no.", accepted:["no"], solution:"Answer: no", required:false),
  Exercise(id:"python-c3-t1-assessment-complete-2-v1", topic:"python-c3-t1", category:"Assessment", type:"short", title:"Understanding check 3", prompt:"Can repeatedly converting unchanged bad text recover by itself? Answer yes or no.", accepted:["no"], solution:"Answer: no", required:false),
  Exercise(id:"python-c3-t1-assessment-complete-3-v1", topic:"python-c3-t1", category:"Assessment", type:"short", title:"Understanding check 4", prompt:"Which clause is intended for cleanup when leaving a try statement?", accepted:["finally"], solution:"Answer: finally", required:false),
  Exercise(id:"python-c3-t2-classwork-complete-v1", topic:"python-c3-t2", category:"Classwork", type:"code", title:"Positive-target contract", prompt:"Define target_percent(total,target). Arguments must be actual integers (not bool): otherwise raise TypeError. total must be nonnegative and target positive: otherwise raise ValueError. Return total/target*100. Do not print.", tests:[{"input": [], "harness": "result=target_percent(30,60)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "50.0", "comparison": "numeric"}, {"input": [], "harness": "result=target_percent(0,10)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0.0", "comparison": "numeric"}, {"input": [], "harness": "result=target_percent(90,60)\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "150.0", "comparison": "numeric"}, {"input": [], "harness": "try:\n    target_percent(3,0)\nexcept ValueError:\n    print(\"Expected failure\")\nelse:\n    raise AssertionError(\"Expected ValueError\")", "expected": "Expected failure", "comparison": "normalized"}, {"input": [], "harness": "try:\n    target_percent('3',5)\nexcept TypeError:\n    print(\"Expected failure\")\nelse:\n    raise AssertionError(\"Expected TypeError\")", "expected": "Expected failure", "comparison": "normalized"}, {"input": [], "harness": "try:\n    target_percent(True,5)\nexcept TypeError:\n    print(\"Expected failure\")\nelse:\n    raise AssertionError(\"Expected TypeError\")", "expected": "Expected failure", "comparison": "normalized"}], hints:["Check the contract before its calculation."], solution:"def target_percent(total,target):\n    if type(total) is not int or type(target) is not int:\n        raise TypeError(\"Integers required\")\n    if total<0 or target<=0:\n        raise ValueError(\"Invalid values\")\n    return total/target*100\n\nReasoning: Check the contract before its calculation. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c3-t2-homework-complete-v1", topic:"python-c3-t2", category:"Homework", type:"code", title:"Exception name observer", prompt:"Define classify_target(total,target). Call target_percent defined in your same submission. Return TypeError or ValueError as text when those exceptions occur; otherwise return Valid. Use the exact contract from classwork.", tests:[{"input": [], "harness": "print(classify_target('30',60))", "expected": "TypeError", "comparison": "normalized"}, {"input": [], "harness": "print(classify_target(30,0))", "expected": "ValueError", "comparison": "normalized"}, {"input": [], "harness": "print(classify_target(30,60))", "expected": "Valid", "comparison": "normalized"}, {"input": [], "harness": "print(classify_target(True,60))", "expected": "TypeError", "comparison": "normalized"}], hints:["Keep error categories distinct instead of returning a generic error."], solution:"def target_percent(total,target):\n    if type(total) is not int or type(target) is not int:\n        raise TypeError(\"Integers required\")\n    if total<0 or target<=0:\n        raise ValueError(\"Invalid values\")\n    return total/target*100\ndef classify_target(total,target):\n    try:\n        target_percent(total,target)\n    except TypeError:\n        return \"TypeError\"\n    except ValueError:\n        return \"ValueError\"\n    return \"Valid\"\n\nReasoning: Keep error categories distinct instead of returning a generic error. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c3-t2-challenge-complete-v1", topic:"python-c3-t2", category:"Challenge", type:"code", title:"Propagating a domain failure", prompt:"Define nonnegative_total(values). Sum the supplied list of actual integers. Raise TypeError for any other element type; raise ValueError for a negative element. Empty input returns zero.", tests:[{"input": [], "harness": "result=nonnegative_total([0,2,3])\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "5", "comparison": "numeric"}, {"input": [], "harness": "result=nonnegative_total([])\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "0", "comparison": "numeric"}, {"input": [], "harness": "result=nonnegative_total([9])\nassert type(result) in (int,float), \"Return a numeric result.\"\nprint(result)", "expected": "9", "comparison": "numeric"}, {"input": [], "harness": "try:\n    nonnegative_total([-1])\nexcept ValueError:\n    print(\"Expected failure\")\nelse:\n    raise AssertionError(\"Expected ValueError\")", "expected": "Expected failure", "comparison": "normalized"}, {"input": [], "harness": "try:\n    nonnegative_total(['3'])\nexcept TypeError:\n    print(\"Expected failure\")\nelse:\n    raise AssertionError(\"Expected TypeError\")", "expected": "Expected failure", "comparison": "normalized"}], hints:["One invalid observation invalidates this function result."], solution:"def nonnegative_total(values):\n    total=0\n    for value in values:\n        if type(value) is not int:\n            raise TypeError(\"Integer required\")\n        if value<0:\n            raise ValueError(\"Negative observation\")\n        total+=value\n    return total\n\nReasoning: One invalid observation invalidates this function result. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
  Exercise(id:"python-c3-t2-project-complete-v1", topic:"python-c3-t2", category:"Project", type:"code", title:"Exceptions chapter: resilient study report", prompt:"Read a valid nonnegative record count, then that many session values as text, then a target as text. Ignore invalid or negative session values and count them as rejected. If target cannot convert to a positive integer, print Invalid target only. Otherwise print Total: N, Accepted: N, Rejected: N, Progress: P% on four lines; P has two decimals. This completes the collected-session report from Chapters 0–2. Explain the error policy in My Notes.", tests:[{"input": ["4", "30", "bad", "-1", "20", "100"], "harness": "", "expected": "Total: 50\nAccepted: 2\nRejected: 2\nProgress: 50.00%", "comparison": "normalized"}, {"input": ["0", "60"], "harness": "", "expected": "Total: 0\nAccepted: 0\nRejected: 0\nProgress: 0.00%", "comparison": "normalized"}, {"input": ["1", "20", "0"], "harness": "", "expected": "Invalid target", "comparison": "normalized"}, {"input": ["1", "20", "bad"], "harness": "", "expected": "Invalid target", "comparison": "normalized"}], hints:["Keep rejected records visible in the report rather than pretending they succeeded."], solution:"count=int(input())\naccepted=[]\nrejected=0\nfor i in range(count):\n    try:\n        value=int(input())\n    except ValueError:\n        rejected+=1\n        continue\n    if value<0:\n        rejected+=1\n    else:\n        accepted.append(value)\ntry:\n    target=int(input())\n    if target<=0:\n        raise ValueError(\"Invalid target\")\nexcept ValueError:\n    print(\"Invalid target\")\nelse:\n    total=sum(accepted)\n    print(f\"Total: {total}\")\n    print(f\"Accepted: {len(accepted)}\")\n    print(f\"Rejected: {rejected}\")\n    print(f\"Progress: {total/target*100:.2f}%\")\n\nReasoning: Keep rejected records visible in the report rather than pretending they succeeded. Test empty/minimum inputs and boundary cases; the reference is one valid implementation.", required:true),
